package com.rohit.inventory.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="stock_transfers") public class StockTransfer extends BaseEntity { @Column(name="transfer_number",nullable=false,unique=true,length=50) private String transferNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="source_warehouse_id",nullable=false) private Warehouse sourceWarehouse; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="destination_warehouse_id",nullable=false) private Warehouse destinationWarehouse; @Enumerated(EnumType.STRING) @Column(nullable=false) private StockTransferStatus status=StockTransferStatus.PENDING; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="requested_by",nullable=false) private User requestedBy; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="approved_by") private User approvedBy; @Column(name="requested_at",nullable=false) private Instant requestedAt=Instant.now(); @Column(name="approved_at") private Instant approvedAt; @Column(name="dispatched_at") private Instant dispatchedAt; @Column(name="received_at") private Instant receivedAt; @Column(name="completed_at") private Instant completedAt; private String remarks; @Column(name="cancellation_reason") private String cancellationReason; @OneToMany(mappedBy="transfer",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.LAZY) private List<StockTransferItem> items=new ArrayList<>(); public String getTransferNumber(){return transferNumber;} public Warehouse getSourceWarehouse(){return sourceWarehouse;} public Warehouse getDestinationWarehouse(){return destinationWarehouse;} public StockTransferStatus getStatus(){return status;} public User getRequestedBy(){return requestedBy;} public Instant getRequestedAt(){return requestedAt;} public User getApprovedBy(){return approvedBy;} public Instant getApprovedAt(){return approvedAt;} public Instant getDispatchedAt(){return dispatchedAt;} public Instant getReceivedAt(){return receivedAt;} public Instant getCompletedAt(){return completedAt;} public String getRemarks(){return remarks;} public List<StockTransferItem> getItems(){return items;} public void setTransferNumber(String v){transferNumber=v;} public void setSourceWarehouse(Warehouse v){sourceWarehouse=v;} public void setDestinationWarehouse(Warehouse v){destinationWarehouse=v;} public void setStatus(StockTransferStatus v){status=v;} public void setRequestedBy(User v){requestedBy=v;} public void setApprovedBy(User v){approvedBy=v;} public void setApprovedAt(Instant v){approvedAt=v;} public void setDispatchedAt(Instant v){dispatchedAt=v;} public void setReceivedAt(Instant v){receivedAt=v;} public void setCompletedAt(Instant v){completedAt=v;} public void setRemarks(String v){remarks=v;} public void setCancellationReason(String v){cancellationReason=v;} public void addItem(StockTransferItem i){items.add(i);i.setTransfer(this);} }
